mapper.select:
SELECT a.*, ISNULL(b.name, '') AS goodsname, ISNULL(c.name, '') AS storagename, ISNULL(d.name, '') AS goodstypename, ISNULL((SELECT TOP 1 u.name FROM sysuser u WHERE u.id = a.userId), '') AS username, ISNULL((SELECT TOP 1 u.name FROM sysuser u WHERE u.id = a.adminId), '') AS adminname FROM record a LEFT JOIN goods b ON a.goods = b.id LEFT JOIN systorage c ON b.storage = c.name LEFT JOIN goodsType d ON b.goodsType = d.name WHERE 1=1
AND a.userId = #{query.userId}
AND c.name = #{query.storage}
AND d.name = #{query.goodsType}
AND b.name LIKE CONCAT('%', #{query.name}, '%')
ORDER BY a.id DESC
